 {"path": "creative_intent.json", "content": "{
  "user_need": "警察男主绑定'犯罪预警系统'，能在凶手额头看到倒计时。他发现未婚妻（法医）额头显示'将在今晚23:00杀害你'。系统提示'不可更改'。他必须在12小时内破解这个'未来命案'，同时不能让她发现他在防备她。随着调查，他发现她杀他的动机是为了阻止他去救一个会导致更大灾难的证人（D20为理想牺牲）。12万字，高密度悬疑。",
  "inspiration_state": "clear_inspiration",
  "extracted_elements": {
    "emotion_verbs": ["绑定", "预警", "杀害", "破解", "防备", "牺牲", "救"],
    "scene_elements": ["警察", "法医", "犯罪预警系统", "倒计时", "12小时", "证人", "灾难", "未来命案"],
    "relationship_tension": ["未婚妻vs未婚夫", "凶手vs受害者", "隐瞒vs调查", "个人爱情vs大众安全", "明知结局却要假装正常"]
  },
  "selected_recipe": {
    "x_axis_mode_id": "D23",
    "x_axis_mode_name": "必须牺牲所爱",
    "y_axis_tags": ["刑侦悬疑", "系统流", "规则怪谈"],
    "reaction_strength": "↘↘",
    "tension_stars": 5,
    "forbidden_elements": ["不要轻松解谜", "不要大团圆结局", "不要让男主轻易逃脱", "不要弱化女主的痛苦"],
    "x_axis_display": "未婚妻必须在23:00亲手杀死男主，系统规则'不可更改'形成绝对压迫，两人在倒计时中相爱相杀",
    "y_axis_combination_effect": "刑侦悬疑提供案件调查框架，系统流增加超自然规则限制，规则怪谈强化'不可更改'的宿命感，三者叠加形成层层递进的绝望氛围",
    "reaction_formula": "系统规则（不可更改）+ 爱情（必须相杀）+ 理想牺牲（阻止灾难）= 极致虐心的悲剧闭环",
    "platform_fit": ["晋江文学城", "豆瓣阅读", "知乎盐选"]
  },
  "one_sentence_synopsis": "警察男主看到未婚妻额头的死亡倒计时，系统提示不可更改，他在12小时内调查真相，发现她杀他是为阻止更大灾难，最终在相爱中完成悲剧宿命。"
}"}

{"path": "characters.json", "content": "{
