        "key_scenes": ["陆沉破解苏清的系统日志", "发现'23:00杀害你'的预言", "两人对峙", "陆沉选择继续任务", "陆沉说'如果你要杀我，现在就动手'"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "第7章：最后的六小时",
        "core_event": "时间来到18:00，陆沉护送证人前往安全屋，苏清被迫跟随，系统倒计时开始具象化（幻听、幻觉），D20病情急剧恶化",
        "emotional_tone": "窒息与倒计时",
        "key_scenes": ["护送途中", "苏清出现幻听", "陆沉握枪戒备", "两人最后的温情时刻", "陆沉暗示苏清他有准备（其实是三年前的旧伤）"]
      }
    ],
    "turning_point": "21:00，证人D20在安全屋突然变异，病毒开始泄露，苏清确认末日倒计时启动，系统强制任务更新：必须立即处决陆沉。苏清内心做出决定——利用陆沉三年前心脏手术的金属支架位置，精准射击制造假死。"
  },
  "act_three": {
    "description": "第三幕：悲剧的终章（21:00-23:00）- 预言成真、双重死亡、世界重置",
    "key_chapters": [
      {
        "chapter_number": 8,
        "chapter_title": "第8章：23:00的抉择",
        "core_event": "22:00，病毒泄露不可逆转，系统强制苏清执行处决。22:55，陆沉与苏清最后对峙，他交出配枪，充满绝望地等待死亡",
        "emotional_tone": "悲怆与决绝",
        "key_scenes": ["病毒警报响起", "系统最后通牒", "陆沉交出配枪", "最后的告白", "陆沉说'我不怪你，这是你的职责'", "苏清含泪举枪"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "第9章：枪响之时",
        "core_event": "23:00整，苏清精准射击陆沉心脏位置的金属支架区域（三年前手术留下的旧伤），子弹偏转制造医学死亡状态，预言成真。系统立即启动收容机制，苏清在陆沉尸体旁开始消失",
        "emotional_tone": "绝望与虚无",
        "key_scenes": ["倒计时归零", "枪声响起", "陆沉倒下（假死，带着绝望）", "苏清开始透明化", "系统提示任务完成", "苏清在消失前最后看了一眼陆沉"]
      },
      {
        "chapter_number": 10,
        "chapter_title": "第10章：被遗忘的复活",
        "core_event": "23:05，苏清彻底消失（物理+记忆抹除）。23:10，陆沉因假死装置自动触发复活机制醒来，发现D20已死，世界安全了，但苏清不存在了",
        "emotional_tone": "空虚与疯狂",
        "key_scenes": ["苏清消失过程", "陆沉复活", "发现D20尸体", "询问同事苏清下落", "所有人都说'谁是苏清？'", "陆沉摸到胸口的枪伤和金属支架变形", "发现子弹精准避开了心脏", "明白苏清救了他", "但苏清已经被抹除"]
      }
    ],
    "turning_point": "23:10，陆沉复活后明白真相——苏清用精准的法医技术救了他，但他死前的最后一刻却恨过她。这种无法弥补的追悔感达到顶点。他摸到口袋里的婚戒，证明这一切不是梦，但世界上已无人记得苏清。"
  }
}"}

environment.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "characters.schema.json",
  "title": "小说人物设计",
  "description": "人物一致性的参考依据，避免角色崩坏",
  "type": "object",
  "required": ["main_characters"],
  "properties": {
    "main_characters": {
      "type": "array",
      "description": "主角/核心角色数组",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "name",
          "role",
          "traits",
          "overt_motivation",
          "covert_motivation",
          "secret_fear"
        ],
        "properties": {
          "name": {
            "type": "string",
            "description": "角色姓名"
          },
          "role": {
            "type": "string",
            "enum": ["protagonist", "deuteragonist"],
            "description": "角色类型：protagonist=第一主角，deuteragonist=第二主角"
          },
          "identity": {
            "type": "string",
            "description": "身份职业/社会角色"
          },
          "traits": {
            "type": "array",
            "description": "核心性格特质关键词（3-5个）",
            "items": {
              "type": "string"
            },
            "minItems": 3,
            "maxItems": 5
          },
          "overt_motivation": {
            "type": "string",
            "description": "显性动机（表面目标）"
          },
          "covert_motivation": {
            "type": "string",
            "description": "隐性动机（深层需求）"
          },
          "secret_fear": {
            "type": "string",
            "description": "秘密恐惧（内心脆弱点）"
          },
          "misperception_of_other": {
            "type": "string",
            "description": "对其他主角的错位认知"
          },
          "hidden_connection": {
            "type": "string",
            "description": "与其他角色的隐藏连接"
          }
        }
      }
    },
    "supporting_characters": {
      "type": "array",
      "description": "配角/次要角色数组",
      "items": {
        "type": "object",
        "required": ["name", "function"],
        "properties": {
          "name": {
            "type": "string",
            "description": "配角姓名"
          },
          "function": {
            "type": "string",
            "enum": ["助力", "阻碍", "反转点"],
            "description": "对主角的作用类型"
          },
          "identity": {
            "type": "string",
            "description": "配角身份"
          },
          "description": {
            "type": "string",
            "description": "配角简要描述"
          }
        }
      }
    },
    "relationship_dynamics": {
      "type": "string",
      "description": "角色关系动态描述"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "creative_intent.schema.json",
  "title": "小说创作意图配方",
  "description": "记录用户需求理解和配方选择结果，作为创作的北极星",
  "type": "object",
  "required": ["user_need", "inspiration_state", "extracted_elements", "selected_recipe", "one_sentence_synopsis"],
  "properties": {
    "user_need": {
      "type": "string",
      "description": "用户的原始输入文本",
      "minLength": 1
    },
    "inspiration_state": {
      "type": "string",
      "enum": ["no_inspiration", "vague_inspiration", "clear_inspiration"],
      "description": "用户创作时的灵感清晰程度"
    },
    "extracted_elements": {
      "type": "object",
      "description": "从用户输入中提取的创作关键要素",
      "required": ["emotion_verbs", "scene_elements", "relationship_tension"],
      "properties": {
        "emotion_verbs": {
          "type": "array",
          "description": "情感动词/核心动作（决定X轴剧情模式）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "scene_elements": {
          "type": "array",
          "description": "场景要素/世界观元素（决定Y轴标签）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "relationship_tension": {
          "type": "array",
          "description": "人物关系张力/冲突来源",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "user_preferences": {
          "type": "object",
          "description": "用户的情感偏好和禁忌",
          "properties": {
            "desired_emotion": {
              "type": "string",
              "description": "期望的情感倾向"
            },
            "forbidden": {
              "type": "array",
              "description": "明确拒绝的元素",
              "items": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "selected_recipe": {
      "type": "object",
      "description": "用户选定的创作配方（X-Y轴化学反应组合）",
      "required": [
        "x_axis_mode_id",
        "x_axis_mode_name",
        "y_axis_tags",
        "reaction_strength",
        "tension_stars",
        "forbidden_elements"
      ],
      "properties": {
        "x_axis_mode_id": {
          "type": "string",
          "pattern": "^[A-G]\\d{1,2}$",
          "enum": [
            "A1", "A2", "A3", "A4", "A5", "A6",
            "B7", "B8", "B9", "B10", "B11", "B12",
            "C13", "C14", "C15", "C16", "C17", "C18",
            "D19", "D20", "D21", "D22", "D23",
            "E24", "E25", "E26", "E27", "E28",
            "F29", "F30", "F31", "F32", "F33", "F34",
            "G35", "G36"
          ],
          "description": "普罗蒂36种剧情模式的标识符"
        },
        "x_axis_mode_name": {
          "type": "string",
          "description": "X轴模式的中文名称"
        },
        "y_axis_tags": {
          "type": "array",
          "description": "现代网文核心标签（表达载体）",
          "items": {
            "type": "string",
            "enum": [
              "双向暗恋",
              "系统流",
              "无限流",
              "种田流",
              "赛博朋克",
              "规则怪谈",
              "重生/穿越",
              "商战权谋",
              "克苏鲁",
              "第四天灾",
              "仙侠修真",
              "刑侦悬疑"
            ]
          },
          "minItems": 2,
          "maxItems": 3
        },
        "reaction_strength": {
          "type": "string",
          "enum": ["↗", "↘", "✷"],
          "description": "X轴与Y轴的化学反应强度符号"
        },
        "tension_stars": {
          "type": "integer",
          "minimum": 1,
          "maximum": 5,
          "description": "故事张力指数（1-5星）"
        },
        "forbidden_elements": {
          "type": "array",
          "description": "避雷红线（创作禁忌元素）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "x_axis_display": {
          "type": "string",
          "description": "X轴模式在故事中的具体显影方式"
        },
        "y_axis_combination_effect": {
          "type": "string",
          "description": "Y轴标签组合产生的效应描述"
        },
        "reaction_formula": {
          "type": "string",
          "description": "化学反应公式的一句话描述"
        },
        "platform_fit": {
          "type": "array",
          "description": "适合发布的平台类型",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "one_sentence_synopsis": {
      "type": "string",
      "description": "一句话故事梗概（30-50字）",
      "minLength": 30,
      "maxLength": 50
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "outline.schema.json",
  "title": "小说故事大纲",
  "description": "节奏规划参考，确保故事有合理的起承转合",
  "type": "object",
  "required": ["act_one", "act_two", "act_three"],
  "properties": {
    "act_one": {
      "type": "object",
      "description": "第一幕：开篇（20-30%篇幅）- 建立世界观、引入主角和核心冲突",
